const MFX_STYLE = "\n.mfx{--bg:#eef1f4;--ink:#1c2733;--dim:#6b7a8b;--line:#e1e7ee;--card:#fff;--accent:#1f6f43}\n.mfx *{box-sizing:border-box;margin:0}\n.mfx body{font-family:'Segoe UI',system-ui,-apple-system,Roboto,Arial,sans-serif;color:var(--ink);background:var(--bg)}\n.mfx .wrap{max-width:1640px;margin:0 auto;padding:18px clamp(10px,2.2vw,26px) 46px}\n.mfx .head{display:flex;align-items:center;gap:13px;flex-wrap:wrap}\n.mfx .logo{width:44px;height:44px;border-radius:11px;background:var(--accent);display:grid;place-items:center;color:#fff;font-weight:800;font-size:20px;flex:0 0 auto}\n.mfx .head h1{font-size:clamp(18px,2.4vw,25px);font-weight:800;letter-spacing:.2px}\n.mfx .head p{font-size:11.5px;color:var(--dim);letter-spacing:2px;text-transform:uppercase;margin-top:1px}\n.mfx .controls{display:flex;gap:8px;flex-wrap:wrap;margin:13px 0}\n.mfx .btn{display:inline-flex;align-items:center;gap:7px;padding:8px 13px;border-radius:10px;border:1px solid var(--line);background:#fff;color:#41525f;font-size:12.5px;font-weight:600;cursor:pointer;transition:.16s;user-select:none}\n.mfx .btn:hover{border-color:#b9c6d3;box-shadow:0 2px 8px rgba(20,40,70,.06)}\n.mfx .btn.on{background:var(--accent);border-color:var(--accent);color:#fff}\n.mfx .btn .ic{width:9px;height:9px;border-radius:3px;background:currentColor;opacity:.7}\n.mfx .layout{display:grid;grid-template-columns:1fr 392px;gap:16px}\n@media(max-width:1000px){.mfx .layout{grid-template-columns:1fr}}\n.mfx .leftcol{display:flex;flex-direction:column;gap:16px;min-width:0}\n.mfx .calc{background:#fff;border:1px solid var(--line);border-radius:16px;box-shadow:0 12px 30px rgba(20,40,70,.08);padding:16px 18px}\n.mfx .ctitle{font-size:15px;font-weight:800;color:#15202b;margin-bottom:3px;display:flex;align-items:center;gap:8px}\n.mfx .ctitle small{font-weight:600;color:var(--dim);font-size:12px}\n.mfx .csub{font-size:12px;color:var(--dim);margin-bottom:13px}\n.mfx .cinputs{display:grid;grid-template-columns:1.5fr 1fr 1fr 1.2fr;gap:10px}\n@media(max-width:680px){.mfx .cinputs{grid-template-columns:1fr 1fr}}\n.mfx .cfield{display:flex;flex-direction:column;gap:4px;font-size:10.5px;color:var(--dim);font-weight:700;text-transform:uppercase;letter-spacing:.4px}\n.mfx .cfield select, .mfx .cfield input{font-size:15px;font-weight:600;color:#15202b;border:1px solid #d8e0e8;border-radius:9px;padding:9px 10px;background:#fff;font-family:inherit;width:100%}\n.mfx .cfield input:focus, .mfx .cfield select:focus{outline:none;border-color:var(--accent);box-shadow:0 0 0 3px rgba(31,111,67,.12)}\n.mfx .cres{margin-top:14px}\n.mfx .cempty{color:#9aa7b4;font-size:13px;padding:6px 2px}\n.mfx .cgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}\n@media(max-width:680px){.mfx .cgrid{grid-template-columns:1fr 1fr}}\n.mfx .cstat{border:1px solid #e6ebf1;border-radius:12px;padding:12px 10px;text-align:center;background:#f7fafc}\n.mfx .cstat .cn{font-size:21px;font-weight:800;color:#15202b;font-variant-numeric:tabular-nums}\n.mfx .cstat .cl{font-size:10px;color:#7c8a98;text-transform:uppercase;letter-spacing:.3px;margin-top:4px;line-height:1.3}\n.mfx .cmsg{margin-top:12px;padding:10px 13px;border-radius:10px;font-size:13px;line-height:1.5}\n.mfx .cmsg.good{background:#eef7ef;border:1px solid #bfe3c4;color:#1f6f43}\n.mfx .cmsg.warn{background:#fff7e8;border:1px solid #f0d79a;color:#7d5a0e}\n.mfx .cmsg.bad{background:#fdeeee;border:1px solid #f0bcbc;color:#a23333}\n.mfx .cmsg.info{background:#eef3f8;border:1px solid #d4e0ec;color:#2b4a63;margin-top:8px}\n.mfx .ccheck{display:inline-flex;align-items:center;gap:8px;margin-top:12px;font-size:13px;font-weight:600;color:#41525f;cursor:pointer;user-select:none}\n.mfx .ccheck input{width:17px;height:17px;accent-color:var(--accent);cursor:pointer}\n.mfx .ccheck small{color:#8593a3;font-weight:500}\n.mfx .cfoot{margin-top:12px;font-size:11px;color:#9aa7b4;line-height:1.5}\n.mfx .cfoot b{color:#5b6b7c}\n.mfx .calc.flash{animation:cflash 1.15s ease}\n@keyframes cflash{0%{box-shadow:0 0 0 0 rgba(31,111,67,0),0 12px 30px rgba(20,40,70,.08)}25%{box-shadow:0 0 0 4px rgba(31,111,67,.30),0 14px 32px rgba(20,40,70,.16)}100%{box-shadow:0 0 0 0 rgba(31,111,67,0),0 12px 30px rgba(20,40,70,.08)}}\n.mfx .gocalc{margin-top:15px;width:100%;border:0;border-radius:11px;background:var(--accent);color:#fff;font-weight:700;font-size:13.5px;padding:11px;cursor:pointer;font-family:inherit;transition:.16s}\n.mfx .gocalc:hover{background:#185b37}\n.mfx .plusbtn{margin-top:12px;width:100%;border:1px dashed #c9a23a;background:#fffaf0;color:#8a6310;font-weight:700;font-size:13px;padding:12px;border-radius:11px;cursor:pointer;font-family:inherit;transition:.16s;text-align:center}\n.mfx .plusbtn:hover{background:#fff3d6}\n.mfx .plusbtn b{color:#7a5500}\n.mfx .brand{display:inline-flex;align-items:center;gap:10px}\n.mfx .brand .bx{background:#2f6e4e;color:#fff;font-weight:800;font-size:18px;letter-spacing:1px;border-radius:10px;padding:6px 11px;line-height:1}\n.mfx .brand .nm{font-weight:800;letter-spacing:3px;color:#15202b;font-size:18px}\n.mfx .brand.hdr{margin-left:auto}\n@media(max-width:640px){.mfx .brand.hdr{display:none}}\n.mfx .brand.big{justify-content:center}.mfx .brand.big .bx{font-size:22px;padding:8px 13px}.mfx .brand.big .nm{font-size:22px;color:#fff}\n.mfx .logobox{display:inline-flex;align-items:center;gap:7px;background:#fff;border:1px solid #e6ebf1;border-radius:10px;padding:6px 11px}\n.mfx .logobox .si{color:#2d6a4a;font-weight:900;font-size:14px;letter-spacing:.4px;font-family:'Arial Black','Arial',sans-serif}\n.mfx .logobox .nm{font-weight:800;letter-spacing:1.5px;color:#3a4753;font-size:13.5px}\n.mfx .logobox.hdr{margin-left:auto;opacity:.9}\n@media(max-width:640px){.mfx .logobox.hdr{display:none}}\n.mfx .logobox.big{padding:9px 15px}.mfx .logobox.big .si{font-size:18px}.mfx .logobox.big .nm{font-size:17px;color:#15202b}\n.mfx .contact .logobox{margin-bottom:14px}\n.mfx .wmark{position:absolute;top:9px;right:9px;display:inline-flex;align-items:center;gap:5px;background:rgba(255,255,255,.72);border:1px solid #e6ebf1;border-radius:7px;padding:3px 8px;opacity:.8;pointer-events:none}\n.mfx .wmark .si{color:#2d6a4a;font-weight:900;font-size:10.5px;font-family:'Arial Black','Arial',sans-serif}\n.mfx .wmark .nm{font-weight:800;letter-spacing:.7px;color:#5b6b7c;font-size:9.5px}\n.mfx .contact{margin-top:18px;background:linear-gradient(180deg,#10402c,#16523b);border-radius:16px;padding:16px 22px;text-align:center}\n.mfx .contact .brand.big{margin-bottom:12px}\n.mfx .contact h3{font-size:17px;font-weight:800;color:#fff;margin-bottom:11px}\n.mfx .contact .ctas{display:flex;gap:9px;justify-content:center;flex-wrap:wrap}\n.mfx .contact .cta{display:inline-flex;align-items:center;gap:7px;padding:11px 20px;border-radius:11px;font-weight:700;font-size:14px;text-decoration:none;transition:.16s}\n.mfx .contact .cta.lotes{background:#fff;color:#10402c;font-size:15px;padding:13px 24px}\n.mfx .contact .cta.wa{background:#25d366;color:#06311a}\n.mfx .contact .cta:hover{transform:translateY(-1px);box-shadow:0 8px 20px rgba(0,0,0,.28)}\n.mfx .contact .fb{margin-top:12px;font-size:12.5px;color:#a3cfb6;display:flex;align-items:center;justify-content:center;gap:10px;flex-wrap:wrap}\n.mfx .contact .faces{display:inline-flex;gap:6px}\n.mfx .contact .face{display:inline-flex;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.22);border-radius:10px;line-height:0;padding:5px;cursor:pointer;transition:.15s}\n.mfx .contact .face svg{display:block}\n.mfx .contact .face:hover{transform:scale(1.15);background:rgba(255,255,255,.2);filter:none}\n.mfx .contact .face.sel{background:#fff;border-color:#fff;transform:scale(1.18);filter:none}\n.mfx .contact .fbthx{color:#fff;font-weight:700}\n.mfx .mapcard{position:relative;background:#fff;border:1px solid var(--line);border-radius:16px;overflow:hidden;box-shadow:0 12px 30px rgba(20,40,70,.08);min-height:460px}\n.mfx svg.map{display:block;width:100%;height:auto;touch-action:none;cursor:grab}\n.mfx svg.map.grab{cursor:grabbing}\n.mfx .zone polygon{fill:var(--c);fill-opacity:.30;stroke:var(--c);stroke-width:.7;stroke-opacity:.75;vector-effect:non-scaling-stroke;cursor:pointer;transition:fill-opacity .18s}\n.mfx .zone:hover polygon, .mfx .zone.active polygon{fill-opacity:.62;stroke-width:1.8;stroke-opacity:1;filter:url(#sh)}\n.mfx #zlayer.dim .zone:not(.match) polygon{fill-opacity:.08;stroke-opacity:.25}\n.mfx .zlabel{font-size:5.4px;font-weight:800;fill:#15202b;stroke:#fff;stroke-width:1.1px;paint-order:stroke;text-anchor:middle;pointer-events:none;opacity:0;transition:opacity .18s}\n.mfx .zone:hover .zlabel, .mfx .zone.active .zlabel{opacity:1;font-size:8px}\n.mfx #zlayer.codes .zlabel{opacity:.95}\n.mfx .sector polygon{fill:#E8A33D;fill-opacity:.05;stroke:#d98012;stroke-width:1.3;stroke-opacity:.85;stroke-dasharray:5 4;vector-effect:non-scaling-stroke;cursor:pointer}\n.mfx .sector:hover polygon, .mfx .sector.active polygon{fill-opacity:.22}\n.mfx .sector text{font-size:11px;font-weight:800;fill:#a85d00;stroke:#fff;stroke-width:2.4px;paint-order:stroke;text-anchor:middle;pointer-events:none}\n.mfx #slayer, .mfx #rlayer .rtag{display:none}\n.mfx #slayer.show{display:block}\n.mfx #rlayer.show .rtag{display:block}\n.mfx #rlayer{display:none}\n.mfx #rlayer.show{display:block}\n.mfx .veil{fill:#fff;opacity:0;transition:opacity .25s;pointer-events:none}\n.mfx .veil.on{opacity:.5}\n.mfx .legend{position:absolute;left:12px;bottom:11px;display:flex;flex-wrap:wrap;gap:6px;max-width:72%}\n.mfx .chip{display:flex;align-items:center;gap:6px;background:rgba(255,255,255,.93);border:1px solid var(--line);border-radius:20px;padding:5px 10px;font-size:12px;font-weight:600;color:#33424f;cursor:pointer;transition:.15s}\n.mfx .chip:hover{box-shadow:0 0 0 2px var(--c) inset;color:#1c2733}\n.mfx .chip i{width:11px;height:11px;border-radius:50%;background:var(--c)}\n.mfx .hud{position:absolute;right:11px;bottom:11px;display:flex;flex-direction:column;gap:6px}\n.mfx .hud button{width:34px;height:34px;border-radius:9px;border:1px solid var(--line);background:#fff;color:#41525f;font-size:17px;cursor:pointer;box-shadow:0 2px 8px rgba(20,40,70,.08)}\n.mfx .hud button:hover{border-color:#b9c6d3}\n.mfx .panel{position:sticky;top:14px;align-self:start;background:#fff;border:1px solid var(--line);border-radius:16px;box-shadow:0 12px 30px rgba(20,40,70,.08);overflow:hidden;min-height:460px}\n.mfx .ph{padding:18px 20px 14px;border-bottom:1px solid var(--line)}\n.mfx .ph .badge{font-size:11px;letter-spacing:1.4px;text-transform:uppercase;color:var(--dim);font-weight:700}\n.mfx .ph .code{display:flex;align-items:center;gap:10px;margin-top:7px}\n.mfx .ph .dot{width:18px;height:18px;border-radius:5px;background:var(--c)}\n.mfx .ph h2{font-size:29px;font-weight:800;color:#15202b}\n.mfx .ph .sub{font-size:13.5px;color:var(--dim);margin-top:3px}\n.mfx .pbody{padding:14px 20px 18px}\n.mfx .metric{margin:13px 0}\n.mfx .metric .k{display:flex;justify-content:space-between;align-items:baseline;font-size:12px;color:var(--dim)}\n.mfx .metric .k b{color:#15202b;font-size:20px;font-weight:800;font-variant-numeric:tabular-nums}\n.mfx .metric .k small{color:#9aa7b4;font-weight:600}\n.mfx .track{height:9px;background:#eef1f4;border-radius:6px;margin-top:7px;overflow:hidden}\n.mfx .track i{display:block;height:100%;border-radius:6px;background:var(--c);width:0;transition:width .55s cubic-bezier(.2,.8,.2,1)}\n.mfx .note{background:#f3f7f4;border-left:3px solid var(--accent);padding:9px 12px;border-radius:8px;font-size:12.5px;color:#3d5546;margin:13px 0;line-height:1.5}\n.mfx .note b{color:#15202b}\n.mfx .grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:4px}\n.mfx .cell{border:1px solid #e6ebf1;border-radius:11px;padding:10px 12px}\n.mfx .cell .l{font-size:10.5px;color:#8593a3;text-transform:uppercase;letter-spacing:.5px}\n.mfx .cell .v{font-size:18px;font-weight:800;margin-top:2px}\n.mfx .alt{display:flex;align-items:flex-end;gap:5px;height:40px;margin-top:7px}\n.mfx .alt i{width:15px;border-radius:3px 3px 0 0;background:var(--c);opacity:.85}\n.mfx .esq{margin-top:12px;border:1px solid #e6ebf1;border-radius:11px;padding:10px 12px;font-size:12px;color:var(--dim);line-height:1.6}\n.mfx .esq h4{font-size:10.5px;letter-spacing:1px;text-transform:uppercase;color:#15202b;margin-bottom:4px}\n.mfx .hint{padding:30px 22px;text-align:center;color:var(--dim)}\n.mfx .hint .ic{width:52px;height:52px;border-radius:13px;background:#eef4f0;color:var(--accent);display:grid;place-items:center;margin:0 auto 13px;font-size:24px}\n.mfx .hint h3{color:#15202b;font-size:16px;margin-bottom:6px}\n.mfx .hint p{font-size:13px;line-height:1.55}\n.mfx .notes{margin-top:15px}\n.mfx .notes details{background:#fff;border:1px solid var(--line);border-radius:12px;margin-bottom:8px;overflow:hidden}\n.mfx .notes summary{cursor:pointer;padding:12px 16px;font-weight:700;font-size:13px;list-style:none;display:flex;justify-content:space-between;color:#2b3947}\n.mfx .notes summary::after{content:\"+\";color:var(--accent);font-size:17px}\n.mfx .notes details[open] summary::after{content:\"–\"}\n.mfx .notes .nb{padding:0 16px 13px;color:var(--dim);font-size:12.5px;line-height:1.65}\n.mfx .notes .nb b{color:#15202b}\n.mfx .foot{margin-top:16px;color:#9aa7b4;font-size:11px;text-align:center;line-height:1.6}\n"
